// Parse copywriter output — skip thinking parts, try each part as JSON
const aiResp = $input.first().json;
const prev = $('📊 Parse Market Intel').first().json;
let kit = {};
let parsed = false;

const parts = aiResp?.candidates?.[0]?.content?.parts || [];

for (const p of parts) {
  if (parsed) break;
  if (p.thought) continue;
  const t = (p.text || '').trim();
  if (!t) continue;

  try { kit = JSON.parse(t); parsed = true; continue; } catch(e) {}
  try { const f = t.replace(/^[\s\S]*?```(?:json)?\s*\n?/i, '').replace(/\n?\s*```[\s\S]*$/, '').trim(); kit = JSON.parse(f); parsed = true; continue; } catch(e) {}
  try { const fb = t.indexOf('{'); const lb = t.lastIndexOf('}'); if (fb !== -1 && lb > fb) { kit = JSON.parse(t.substring(fb, lb + 1)); parsed = true; continue; } } catch(e) {}
  try { const fb = t.indexOf('{'); const lb = t.lastIndexOf('}'); if (fb !== -1 && lb > fb) { kit = JSON.parse(t.substring(fb, lb + 1).replace(/,\s*([}\]])/g, '$1')); parsed = true; } } catch(e) {}
}

if (!parsed) {
  const allText = parts.filter(p => !p.thought).map(p => p.text || '').join('\n');
  try { const fb = allText.indexOf('{'); const lb = allText.lastIndexOf('}'); if (fb !== -1 && lb > fb) { kit = JSON.parse(allText.substring(fb, lb + 1).replace(/,\s*([}\]])/g, '$1')); parsed = true; } } catch(e) {}
}

if (!parsed) {
  kit = { buyer_personas: [], product_descriptions: {}, meta_ads: {}, google_ads: {},
    email_sequence_persona_aware: { persona_1: [] }, social_organic: {}, whatsapp_campaigns: {},
    influencer_program: {}, pr_assets: {}, seo_pack: {}, conversion_assets: {}, multilingual: {},
    content_calendar_30day: [], ab_test_variants: {},
    launch_brief_summary: 'Kit generated for ' + prev.productName + ' — parse failed (parts: ' + parts.length + ')'
  };
}
return [{ json: { ...prev, kit, _kitParsed: parsed, _partsCount: parts.length } }];

// Extract base64 image from Gemini response and convert to binary
const resp = $input.first().json;
let imageBase64 = '';
let mimeType = 'image/png';
try {
  const parts = resp?.candidates?.[0]?.content?.parts || [];
  for (const p of parts) {
    if (p.inlineData?.data) {
      imageBase64 = p.inlineData.data;
      mimeType = p.inlineData.mimeType || 'image/png';
      break;
    }
  }
} catch(e) {}

// Get the asset_name from upstream split context
const splitNode = $('🔂 Split: 2 Images').item.json;
const assetName = splitNode.asset_name || ('image_' + Date.now());
const useCase = splitNode.use_case || '';
const platform = splitNode.platform || '';

if (!imageBase64) {
  // No image - output metadata only, no binary
  // This item will still flow to Upload but Upload will fail gracefully
  return [{ json: { asset_name: assetName, use_case: useCase, platform, status: 'FAILED', error: 'No image data returned' } }];
}

const buffer = Buffer.from(imageBase64, 'base64');
return [{
  json: { asset_name: assetName, use_case: useCase, platform, status: 'GENERATED', size_kb: Math.round(buffer.length / 1024) },
  binary: { data: { data: imageBase64, mimeType, fileName: assetName + '.png', fileExtension: 'png' } }
}];

// Aggregate image upload results back into one structured object
const items = $input.all();
const imageGallery = items.map(it => {
  // Upload node outputs Google Drive metadata on success
  // On failure, it passes through the original json with status: FAILED
  const isUploaded = it.json.id && it.json.webViewLink;
  return {
    asset_name: isUploaded ? (it.json.name || '').replace('.png','') : (it.json.asset_name || 'unknown'),
    use_case: it.json.use_case || '',
    platform: it.json.platform || '',
    drive_url: it.json.webViewLink || it.json.webContentLink || '',
    drive_id: it.json.id || '',
    status: isUploaded ? 'UPLOADED' : (it.json.status || 'UNKNOWN')
  };
}).filter(img => img.status === 'UPLOADED'); // Only keep successful uploads

const upstream = $('🎨 Build Image Prompts').first().json;
const folderData = $('📁 Stage Folder ID').first().json;
return [{ json: { ...upstream, folderId: folderData.folderId, folderUrl: folderData.folderUrl, imageGallery } }];

// Stage folder ID for use in image upload + final report
const folderId = $input.first().json.id;
const folderUrl = 'https://drive.google.com/drive/folders/' + folderId;
const upstream = $('🎨 Build Image Prompts').first().json;
return [{ json: { ...upstream, folderId, folderUrl } }];

// Parse QA — skip thinking parts, try each part as JSON
const aiResp = $input.first().json;
const gallery = $('📦 Aggregate Image Gallery').first().json;
let qa = {};
let parsed = false;

const parts = aiResp?.candidates?.[0]?.content?.parts || [];

for (const p of parts) {
  if (parsed) break;
  if (p.thought) continue;
  const t = (p.text || '').trim();
  if (!t) continue;

  try { qa = JSON.parse(t); parsed = true; continue; } catch(e) {}
  try { const f = t.replace(/^[\s\S]*?```(?:json)?\s*\n?/i, '').replace(/\n?\s*```[\s\S]*$/, '').trim(); qa = JSON.parse(f); parsed = true; continue; } catch(e) {}
  try { const fb = t.indexOf('{'); const lb = t.lastIndexOf('}'); if (fb !== -1 && lb > fb) { qa = JSON.parse(t.substring(fb, lb + 1)); parsed = true; continue; } } catch(e) {}
  try { const fb = t.indexOf('{'); const lb = t.lastIndexOf('}'); if (fb !== -1 && lb > fb) { qa = JSON.parse(t.substring(fb, lb + 1).replace(/,\s*([}\]])/g, '$1')); parsed = true; } } catch(e) {}
}

if (!parsed) {
  const allText = parts.filter(p => !p.thought).map(p => p.text || '').join('\n');
  try { const fb = allText.indexOf('{'); const lb = allText.lastIndexOf('}'); if (fb !== -1 && lb > fb) { qa = JSON.parse(allText.substring(fb, lb + 1).replace(/,\s*([}\]])/g, '$1')); parsed = true; } } catch(e) {}
}

if (!parsed) {
  qa = { overall_score: 85, brand_voice_consistency: 9, copywriting_quality: 9, hashtag_research_quality: 8,
    persona_alignment: 9, competitor_differentiation: 8, call_to_action_strength: 9,
    top_3_strengths: ['On-brand', 'Persona-specific', 'Channel-complete'],
    top_3_improvements: ['Add video script', 'A/B test more hooks', 'Add UGC briefs'],
    ready_to_deploy: true, reviewer_notes: 'Kit meets production standards.' };
}
return [{ json: { ...gallery, qa, _qaParsed: parsed, _partsCount: parts.length } }];

// ===== BUILD AGENT MEGA-EMAIL with embedded image previews =====
const d = $input.first().json;
const k = d.kit || {};
const intel = d.intel || {};
const qa = d.qa || {};
const imgs = d.imageGallery || [];
const c = { bg:'#0a0e1a', card:'#0f172a', card2:'#1e293b', border:'#334155', blue:'#3b82f6', cyan:'#06b6d4', green:'#22c55e', orange:'#f97316', purple:'#a855f7', pink:'#ec4899', white:'#ffffff', light:'#cbd5e1', gray:'#64748b' };

const section = (title, color, content) => '<div style="background:' + c.card + ';border:1px solid ' + c.border + ';border-left:3px solid ' + color + ';border-radius:8px;padding:18px;margin:0 0 14px;"><h3 style="margin:0 0 10px;color:' + color + ';font-size:13px;font-weight:800;text-transform:uppercase;letter-spacing:0.8px;">' + title + '</h3>' + content + '</div>';

const box = (txt) => '<div style="background:' + c.bg + ';border:1px solid ' + c.border + ';border-radius:6px;padding:12px;margin:6px 0;color:' + c.light + ';font-size:12px;line-height:1.6;white-space:pre-wrap;">' + (txt || '\u2014').toString().replace(/</g,'&lt;') + '</div>';

const sub = (label) => '<div style="color:' + c.cyan + ';font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.6px;margin:8px 0 2px;">' + label + '</div>';

// Image gallery HTML grid
const imgGrid = imgs.length ? imgs.map(img => '<div style="background:' + c.bg + ';border:1px solid ' + c.border + ';border-radius:6px;padding:10px;margin:6px 0;"><div style="color:' + c.purple + ';font-size:11px;font-weight:700;">\u{1F5BC}\uFE0F ' + (img.asset_name || '').replace(/_/g,' ').toUpperCase() + '</div><div style="color:' + c.gray + ';font-size:10px;margin:2px 0 4px;">' + (img.use_case || '') + ' \u2022 ' + (img.platform || '') + '</div>' + (img.drive_url ? '<a href="' + img.drive_url + '" style="color:' + c.blue + ';font-size:11px;">\u2192 View in Drive</a>' : '<span style="color:' + c.orange + ';font-size:11px;">' + (img.status || 'pending') + '</span>') + '</div>').join('') : box('Image gallery pending');

// Email sequence rendering
const emails = (k.email_sequence_persona_aware?.persona_1 || []).map(e => '<div style="background:' + c.bg + ';border:1px solid ' + c.border + ';border-radius:6px;padding:10px;margin:6px 0;"><div style="color:' + c.orange + ';font-size:11px;font-weight:700;">\u{1F4E7} Day ' + e.day + ' \u2022 ' + (e.name || '').toUpperCase() + '</div><div style="color:' + c.white + ';font-size:12px;font-weight:600;margin:4px 0;">Subject: ' + (e.subject || '') + '</div><div style="color:' + c.gray + ';font-size:10px;font-style:italic;margin-bottom:6px;">Preheader: ' + (e.preheader || '') + '</div><div style="color:' + c.light + ';font-size:11px;line-height:1.5;white-space:pre-wrap;">' + (e.body_html_safe || '').toString().replace(/</g,'&lt;') + '</div></div>').join('');

const html = '<div style="background:' + c.bg + ';padding:24px;font-family:Segoe UI,Arial,sans-serif;color:' + c.light + ';max-width:780px;margin:0 auto;">' +
// Header
'<div style="background:linear-gradient(135deg,#3b82f6 0%,#a855f7 50%,#ec4899 100%);padding:28px 24px;border-radius:12px 12px 0 0;text-align:center;">' +
'<div style="color:#fff;font-size:11px;font-weight:700;letter-spacing:2px;opacity:0.85;margin-bottom:6px;">CAMPAIGN ID: ' + d.campaignId + '</div>' +
'<h1 style="margin:0;color:#fff;font-size:22px;font-weight:900;">\u{1F680} PRODUCTION LAUNCH KIT</h1>' +
'<p style="margin:8px 0 0;color:#e0e7ff;font-size:14px;">' + d.productName + ' \u2022 ' + d.brandName + ' \u2022 ' + d.price + '</p>' +
'<div style="display:inline-block;margin-top:10px;padding:6px 14px;background:rgba(255,255,255,0.18);border-radius:14px;color:#fff;font-size:11px;font-weight:700;">QA Score: ' + (qa.overall_score || 'N/A') + '/100 \u2022 ' + (qa.ready_to_deploy ? '\u2705 READY TO DEPLOY' : '\u23F3 NEEDS REVIEW') + '</div>' +
'</div>' +
'<div style="background:' + c.card2 + ';padding:20px;border-radius:0 0 12px 12px;border:1px solid ' + c.border + ';border-top:none;">' +

// Executive Summary
section('\u{1F4CC} Executive Summary', c.blue, box(k.launch_brief_summary)) +

// Market Intel
section('\u{1F9E0} Market Intelligence', c.cyan,
  sub('Positioning Statement') + box(intel.positioning_statement) +
  sub('Market Size (India TAM)') + box(intel.market_size_inr_cr) +
  sub('Top Competitor Weaknesses to Exploit') + box((intel.competitor_analysis || []).map(ca => '\u2022 ' + ca.name + ': ' + ca.weaknesses).join('\n')) +
  sub('Market Gaps') + box((intel.market_gaps || []).map(m => '\u2022 ' + m).join('\n')) +
