const leads = contacts
  .map((item, idx) => {
    const r = item.json;
    const email = (r['Email'] || '').trim();
    const emailStatus = (r['Email Status'] || '').trim();

    // Skip rows without verified email
    if (!email || emailStatus.toLowerCase() !== 'verified') return null;

    const firstName = (r['First Name'] || '').trim();
    const lastName = (r['Last Name'] || '').trim();
    const companyName = (r['Company Name'] || '').trim();
    const title = (r['Title'] || '').trim();
    const industry = (r['Industry'] || '').trim();
    const companySize = (r['# Employees'] || '').toString().trim();
    const keywords = (r['Keywords'] || '').trim();
    const website = (r['Website'] || '').trim();
    const linkedin = (r['Person Linkedin Url'] || '').trim();
    const city = (r['City'] || '').trim();
    const state = (r['State'] || '').trim();
    const country = (r['Country'] || '').trim();
    const revenue = (r['Annual Revenue'] || '').toString().trim();
    const tech = (r['Technologies'] || '').trim();
    const seniority = (r['Seniority'] || '').trim();

    // Build rich company context for AI personalization
    const companyContext = [
      industry ? `Industry: ${industry}` : '',
      companySize ? `${companySize} employees` : '',
      revenue ? `Revenue: ${revenue}` : '',
      keywords ? `Focus areas: ${keywords.slice(0, 150)}` : '',
      tech ? `Tech stack: ${tech.slice(0, 150)}` : '',
      website ? `Website: ${website}` : ''
    ].filter(Boolean).join('. ');

    return {
      leadIndex: idx + 1,
      firstName,
      lastName,
      fullName: `${firstName} ${lastName}`.trim(),
      email,
      title,
      seniority,
      companyName,
      companyIndustry: industry,
      companySize,
      companyKeywords: keywords,
      companyWebsite: website,
      companyRevenue: revenue,
      companyTech: tech,
      companyContext,
      linkedinUrl: linkedin,
      location: [city, state, country].filter(Boolean).join(', '),
      agencyName,
      service,
      uvp,
      senderEmail,
      senderName
    };
  })
  .filter(Boolean);

