    errors: Array.isArray(parsed.errors) ? parsed.errors : [],
    processed_at: new Date().toISOString()
  }
}];

const verified = $('Read Verified sheet').all().map(i => i.json);
const flagged  = $('Read Flagged sheet').all().map(i => i.json);

const today = new Date().toISOString().slice(0, 10);

const todayVerified = verified.filter(r => r.processed_at?.startsWith(today));
const todayFlagged  = flagged.filter(r  => r.processed_at?.startsWith(today));

const totalCount = todayVerified.length + todayFlagged.length;
const passCount  = todayVerified.length;
const failCount  = todayFlagged.length;
const passRate   = totalCount > 0 ? ((passCount / totalCount) * 100).toFixed(1) : '0.0';

const totalAmount = todayVerified.reduce((sum, r) => {
  const v = parseFloat(r.total_amount);
  return sum + (isNaN(v) ? 0 : v);
}, 0);

const currencyMap = {};
for (const r of todayVerified) {
  const c = r.currency || 'UNKNOWN';
  if (!currencyMap[c]) currencyMap[c] = { count: 0, total: 0 };
  currencyMap[c].count++;
  currencyMap[c].total += parseFloat(r.total_amount) || 0;
}

const currencyRows = Object.entries(currencyMap)
  .sort((a, b) => b[1].total - a[1].total)
  .map(([currency, data]) => ({
    currency,
    count: data.count,
    total: data.total.toFixed(2)
  }));

const topErrors = todayFlagged
  .flatMap(r => (r.errors || '').toString().split(','))
  .reduce((acc, e) => {
    const k = e.trim();
    if (k) acc[k] = (acc[k] || 0) + 1;
    return acc;
  }, {});

return [{ json: { today, totalCount, passCount, failCount, passRate, totalAmount: totalAmount.toFixed(2), currencyRows, topErrors } }];

