    ourApproach:             `We follow a structured four-phase methodology: Discovery, Design, Build, and Deploy tailored for ${cleanForm.serviceType}.`,
    scopeOfWork:             '• Requirements discovery and documentation\n• Solution architecture and design\n• Custom development and integrations\n• QA, testing and performance optimisation\n• Deployment, training and 30-day support',
    deliverablesTimeline:    'Phase 1 (Week 1–2): Discovery\nPhase 2 (Week 3–4): Design\nPhase 3 (Week 5–6): Build\nPhase 4 (Week 7–8): Launch & Handover',
    expectedOutcomes:        `1. 50–60% reduction in manual processing time\n2. 3× improvement in data accuracy\n3. Full ROI within 90 days`,
    investmentJustification: `At ₹${cleanForm.budget}, this delivers enterprise-grade AI at a fraction of in-house cost.`
  };
}

const merged = { ...cleanForm, ...ai };

// ── 2. Pre-build Google Slides batchUpdate request body ──
const r = (find, val) => ({
  replaceAllText: {
    containsText: { text: find, matchCase: false },
    replaceText: String(val || '').slice(0, 3000)
  }
});

const slidesBatchUpdate = JSON.stringify({
  requests: [
    r('{{client_name}}',              merged.clientName),
    r('{{company_name}}',             merged.companyName),
    r('{{service_type}}',             merged.serviceType),
    r('{{industry}}',                 merged.industry),
    r('{{date_created}}',             merged.dateCreated),
    r('{{proposal_id}}',              merged.proposalId),
    r('{{timeline}}',                 merged.timeline),
    r('{{budget}}',                   '₹' + merged.budget),
    r('{{total_investment}}',         '₹' + merged.totalAmount),
    r('{{executive_summary}}',        merged.executiveSummary),
    r('{{why_choose_us}}',            merged.whyChooseUs),
    r('{{our_approach}}',             merged.ourApproach),
    r('{{scope_of_work}}',            merged.scopeOfWork),
    r('{{deliverables_timeline}}',    merged.deliverablesTimeline),
    r('{{expected_outcomes}}',        merged.expectedOutcomes),
    r('{{investment_justification}}', merged.investmentJustification)
  ]
});

// ── 3. Pre-build invoice values (used by native Google Sheets node) ──
const invoiceValues = [
  merged.invoiceId,
  merged.dateCreated,
  merged.dueDate,
  merged.clientName,
  merged.companyName,
  merged.clientEmail,
  merged.serviceType,
  merged.timeline,
  merged.subtotal,
  merged.gstAmount,
  merged.totalAmount,
  'Pending Payment',
  'Bank Transfer / UPI / Stripe',
  merged.proposalId,
  'Thank you for choosing us!'
];

return [{ json: { ...merged, slidesBatchUpdate, invoiceValues } }];

// Rename binary 'data' → 'proposalPDF' so we can identify it after the merge
const item     = $input.first();
const formData = $('🔀 Merge AI + Form Data').first().json;
return [{
  json: {
    ...formData,
    proposalFileId: $('📄 Copy Slides Template').first().json.id
  },
  binary: {
    proposalPDF: item.binary?.data
  }
}];

// Rename binary 'data' → 'invoicePDF' so we can identify it after the merge
const item     = $input.first();
const formData = $('🔀 Merge AI + Form Data').first().json;
return [{
  json: {
    ...formData,
    invoiceFileId: $('📊 Copy Invoice Template').first().json.id
  },
  binary: {
    invoicePDF: item.binary?.data
  }
}];

// ─────────────────────────────────────────────────────────────
// NODE 15: Combine proposalPDF + invoicePDF binaries into
// a single item so Gmail can attach both in one email
// ─────────────────────────────────────────────────────────────
const items       = $input.all();
const proposalItem = items.find(i => i.binary?.proposalPDF);
const invoiceItem  = items.find(i => i.binary?.invoicePDF);

if (!proposalItem) throw new Error('❌ proposalPDF binary not found. Check node: Label Proposal PDF');
if (!invoiceItem)  throw new Error('❌ invoicePDF binary not found. Check node: Label Invoice PDF');

// Use formData from the proposal item (both have the same data)
const baseData = $('🔀 Merge AI + Form Data').first().json;

return [{
  json: {
    ...baseData,
    proposalFileId: proposalItem.json.proposalFileId,
    invoiceFileId:  invoiceItem.json.invoiceFileId
  },
  binary: {
    proposalPDF: proposalItem.binary.proposalPDF,
    invoicePDF:  invoiceItem.binary.invoicePDF
  }
}];

// ─────────────────────────────────────────────────────────────
// Parse form input and prepare research parameters
// ─────────────────────────────────────────────────────────────
const form = $input.first().json;

const topic = (form['Topic I Want to Learn'] || '').trim();
const level = (form['My Current Knowledge Level'] || 'Complete Beginner').trim();
const specificQ = (form['What I Specifically Want to Understand'] || '').trim();
const email = (form['Notification Email'] || '').trim();

if (!topic) throw new Error('Topic is required.');
if (!email) throw new Error('Notification email is required.');

const levelContext = {
  'Complete Beginner': 'Explain from absolute scratch. Use simple analogies. Assume zero prior knowledge.',
  'Some Basics': 'Assume basic understanding. Focus on how things work and practical applications.',
  'Intermediate': 'Skip the basics. Go deeper into architecture, trade-offs, and implementation details.',
  'Advanced - Deep Dive Only': 'Expert level. Focus on cutting-edge developments, research papers, advanced techniques, and edge cases.'
};

return [{ json: {
  topic,
  level,
  levelInstruction: levelContext[level] || levelContext['Complete Beginner'],
  specificQuestions: specificQ,
  email,
  timestamp: new Date().toISOString()
}}];

